int set_binprm_credentials(struct linux_binprm *bprm) {
    struct cred *new, *old;
    int ret;

    old = current_cred();
    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    if (bprm->capable & CAP_SETUID) {
        if (old->uid != 0) {
            new->uid = old->uid;
            new->euid = bprm->cred->uid;
        } else {
            new->uid = new->euid = bprm->cred->uid;
        }
    } else {
        new->uid = new->euid = old->uid;
    }

    if (bprm->capable & CAP_SETGID) {
        if (old->gid != 0) {
            new->gid = old->gid;
            new->egid = bprm->cred->gid;
        } else {
            new->gid = new->egid = bprm->cred->gid;
        }
    } else {
        new->gid = new->egid = old->gid;
    }

    new->cap_effective = bprm->cap_effective & old->cap_permitted;
    new->cap_inheritable = bprm->cap_inheritable;
    new->cap_permitted = new->cap_effective | new->cap_inheritable;

    if (new->cap_effective || new->cap_inheritable || new->cap_permitted) {
        audit_log_cap(new);
    }

    ret = set_current_cred(new);
    if (ret < 0) {
        return ret;
    }

    update_securebits(new);

    return 0;
}

int set_binprm_credentials(struct linux_binprm *bprm) {
    const struct cred *old_cred = current_cred();
    struct cred *new_cred;
    int ret = 0;

    if (bprm->cred) {
        return 0;
    }

    new_cred = prepare_creds();
    if (!new_cred) {
        return -ENOMEM;
    }

    if (bprm->file) {
        struct inode *inode = file_inode(bprm->file);

        if (inode) {
            mode_t mode = inode->i_mode;
            if (S_ISUID & mode) {
                if (old_cred->uid != 0) {
                    new_cred->euid = inode->i_uid;
                } else {
                    new_cred->euid = new_cred->uid;
                }
            }

            if (S_ISGID & mode) {
                if (!(old_cred->fsuid_eq(new_cred->euid)) &&
                    (old_cred->gid != 0)) {
                    new_cred->egid = inode->i_gid;
                } else {
                    new_cred->egid = new_cred->gid;
                }
            }
        }
    }

    if (security_capset(new_cred, old_cred, &bprm->cap_inheritable, &bprm->cap_permitted, &bprm->cap_effective)) {
        ret = -EPERM;
        goto out;
    }

    new_cred->securebits = bprm->securebits;

    if (!ptrace_capable()) {
        new_cred->euid = new_cred->uid;
        new_cred->egid = new_cred->gid;
    }

    if (new_cred->euid != new_cred->uid ||
        new_cred->egid != new_cred->gid) {
        new_cred->locked = 0;
    }

    if (task_noaudit()) {
        new_cred->cap_effective = 0;
    }

    ret = security_task_setuid(new_cred->uid, new_cred->euid, new_cred->fsuid, LSM_SETID_RE);
    if (ret) {
        goto out;
    }

    ret = security_task_setgid(new_cred->gid, new_cred->egid, new_cred->fsgid, LSM_SETID_RE);
    if (ret) {
        goto out;
    }

    commit_creds(new_cred);
    bprm->cred = new_cred;

out:
    return ret;
}

int set_binprm_credentials(struct linux_binprm *bprm) {
    const struct cred *old_cred = current_cred();
    struct cred *new_cred;

    /* Retrieve new credentials based on current ones */
    new_cred = prepare_creds();
    if (!new_cred)
        return -ENOMEM;

    /* Handle capabilities and security checks */
    if (bprm->cap_inheritable) {
        if (old_cred->euid == 0) {
            /* Special handling for root */
            if (cap_set_flag(new_cred, CAP_INHERITABLE, CAP_TO_MASK(CAP_SETUID), 1, NULL))
                goto error;
        } else {
            /* Adjust based on user capabilities */
            if (cap_set_flag(new_cred, CAP_EFFECTIVE, CAP_TO_MASK(CAP_FOWNER), 0, NULL))
                goto error;
        }
    }

    /* Clear dangerous flags if not permitted */
    if (!ns_capable(bprm->unsafe, CAP_SETPCAP)) {
        new_cred->cap_bset = CAP_INIT_EFFSET;
        new_cred->cap_ambient = 0;
    }

    /* Enforce tracing permissions */
    if (ptrace_capable()) {
        new_cred->securebits |= SECURE_KEEP_CAPS;
    }

    /* Update audit information if capabilities changed */
    if (memcmp(&new_cred->cap_effective, &old_cred->cap_effective, sizeof(kernel_cap_t))) {
        audit_log_cap(new_cred->cap_effective);
    }

    /* Apply new credentials */
    if (commit_creds(new_cred))
        return -EINVAL;

    return 0;

error:
    abort_creds(new_cred);
    return -EPERM;
}

int set_binprm_credentials(struct linux_binprm *bprm) {
    const struct cred *old_cred = current_cred();
    struct cred *new_cred;
    int ret;

    new_cred = prepare_creds();
    if (!new_cred)
        return -ENOMEM;

    ret = security_task_set_security(new_cred, bprm);
    if (ret)
        goto error;

    if (bprm->unsafe) {
        if (old_cred->euid != old_cred->uid) {
            if (!capable(CAP_SETUID))
                ret = -EPERM;
        }
        if (old_cred->egid != old_cred->gid) {
            if (!capable(CAP_SETGID))
                ret = -EPERM;
        }
        if (ret)
            goto error;
    }

    if (bprm->file_caps) {
        if (bprm->file_caps->inheritable) {
            new_cred->cap_inheritable = bprm->file_caps->inheritable;
        }

        if (bprm->file_caps->permitted) {
            new_cred->cap_permitted = bprm->file_caps->permitted;
        }

        new_cred->cap_effective = new_cred->cap_permitted;
    }

    if (task_dumpable(current)) {
        new_cred->cap_effective &= ~CAP_TO_CLEAN;
    }

    if (ptracer_capable(new_cred)) {
        new_cred->cap_inheritable &= ~CAP_TO_DROP;
    }

    ret = audit_log_new_caps(new_cred);
    if (ret)
        goto error;

    ret = set_current_cred(new_cred);
    if (ret)
        goto error;

    return 0;

error:
    abort_creds(new_cred);
    return ret;
}

int set_binprm_credentials(struct linux_binprm *bprm) {
    const struct cred *old_cred = current_cred();
    struct cred *new_cred;

    new_cred = prepare_creds();
    if (!new_cred)
        return -ENOMEM;

    if (bprm->cred_prepared) {
        if (old_cred != new_cred)
            abort_creds(new_cred);
        return 0;
    }

    if (bprm->file) {
        int ret = security_bprm_set_creds(bprm);
        if (ret < 0) {
            if (old_cred != new_cred)
                abort_creds(new_cred);
            return ret;
        }
    }

    if (bprm->cred) {
        *new_cred = *bprm->cred;
        put_cred(bprm->cred);
    } else {
        *new_cred = *old_cred;
    }

    if (bprm->unsafe & LSM_UNSAFE_SHARE)
        new_cred->securebits &= ~SECURE_NO_SETUID_FIXUP;

    if (bprm->unsafe & LSM_UNSAFE_SETUID)
        new_cred->securebits &= ~SECURE_FORCE_GROUPS;

    if (bprm->file) {
        struct inode *inode = file_inode(bprm->file);

        if (S_ISUID & inode->i_mode) {
            new_cred->uid = i_uid_read(inode);
            new_cred->euid = i_uid_read(inode);
        }

        if (S_ISGID & inode->i_mode) {
            new_cred->gid = i_gid_read(inode);
            new_cred->egid = i_gid_read(inode);
        }
    }

    if (!new_cred->uid_eq(new_cred->euid, new_cred->uid) ||
        !new_cred->euid_eq(new_cred->euid, old_cred->euid) ||
        !new_cred->gid_eq(new_cred->egid, new_cred->gid) ||
        !new_cred->egid_eq(new_cred->egid, old_cred->egid)) {
        if (!ptrace_allow_setid()) {
            if (old_cred != new_cred)
                abort_creds(new_cred);
            return -EPERM;
        }
    }

    bprm->cred = new_cred;
    bprm->cred_prepared = true;

    if (new_cred->effective.cap != 0)
        audit_log_cap(new_cred);

    return 0;
}
